def pref_case(a,queries): return arr(a).replace('\n',f' {len(queries)}\n',1)+''.join(f'{l} {r}\n' for l,r in queries)
def pref_ref(s):
    v=ints(s);n,q=v[:2]; a=v[2:2+n];return '\n'.join(str(sum(a[l-1:r])) for l,r in zip(v[2+n::2],v[3+n::2]))
add("prefix","Сумма отрезка за один шаг","Префиксные суммы",6,"Основной",
"Если много раз суммировать куски списка, прямой перебор повторяет работу. Сохраним p[i] — сумму первых i элементов, p[0] = 0.|p[i+1] = p[i] + a[i]. Сумма с позиции l по r включительно (позиции с 1) равна p[r] - p[l-1]. Длинный отрезок теперь не дороже короткого.",
"a = [3, 1, 4]\np = [0]\nfor x in a:\n    p.append(p[-1] + x)\nprint(p)  # [0, 3, 4, 8]\nprint(p[3] - p[1])  # 1 + 4 = 5",
"Дан список и q запросов. Для каждого выведи сумму элементов с l по r включительно.","n q; затем n чисел; затем q строк l r. 1 ≤ n,q ≤ 200000; 1 ≤ l ≤ r ≤ n; |a[i]| ≤ 10⁹.","q сумм, каждая с новой строки.","n, q = map(int, input().split())\na = list(map(int, input().split()))\np = [0]\n# Построй суммы, затем обработай запросы\n",
"n, q = map(int, input().split())\na = list(map(int, input().split()))\np = [0]\nfor x in a:\n    p.append(p[-1] + x)\nfor _ in range(q):\n    l, r = map(int, input().split())\n    print(p[r] - p[l - 1])",["Начни p с нуля: это сумма пустого префикса.","Добавляй p[-1] + x для каждого числа.","Для l r вычти p[l - 1] из p[r]."],
"Построение p занимает один проход.|Большой префикс содержит нужный отрезок и лишнее слева.|Вычитание удаляет лишнюю часть, в том числе для отрицательных чисел.","O(n + q) времени, O(n) памяти.","Частая ошибка — p[r] - p[l], теряющая первый элемент отрезка.",
("Сумма первого элемента через p?",["p[1] - p[0]","p[0]","p[1] - p[1]"],0,"p[0] — сумма нуля элементов."),[pref_case([3,1,4],[(2,3),(1,1)]),pref_case([-5],[(1,1)]),pref_case([0,0],[(1,2)]),pref_case([-4,7,-2],[(1,3),(2,2)])]+[pref_case([R.randrange(-100,100) for _ in range(20)],[(1,20),(5,15),(20,20)]) for _ in range(4)],pref_ref)

add("binary","Бинарный поиск: каждый раз пополам","Бинарный поиск",7,"Основной",
"Бинарный поиск работает по упорядоченным данным или монотонному условию: сначала ответы «нет», потом «да». Ищем первую позицию a[i] ≥ x.|Держим полуинтервал [l, r), сначала l = 0, r = n. Если a[m] < x, ответ правее: l = m+1. Иначе r = m. При l == r ответ найден; n означает, что подходящего элемента нет.",
"a = [2, 5, 5, 9]\nl, r = 0, len(a)\nwhile l < r:\n    m = (l + r) // 2\n    if a[m] < 5:\n        l = m + 1\n    else:\n        r = m\nprint(l)  # 1",
"В отсортированном списке найди первый элемент не меньше x. Выведи его позицию с 1, либо -1, если такого нет.","n x; затем n чисел в неубывающем порядке. 1 ≤ n ≤ 200000; |значения|, |x| ≤ 10⁹.","Позиция с 1 или -1.","n, x = map(int, input().split())\na = list(map(int, input().split()))\nl, r = 0, n\n# Сужай интервал\n",
"n, x = map(int, input().split())\na = list(map(int, input().split()))\nl, r = 0, n\nwhile l < r:\n    m = (l + r) // 2\n    if a[m] < x:\n        l = m + 1\n    else:\n        r = m\nprint(l + 1 if l < n else -1)",
["Нужен первый подходящий, поэтому при равенстве двигай правую границу.","Условие a[m] < x отбрасывает левую половину вместе с m.","После цикла проверь l < n, затем переведи индекс в позицию."],
"Возможный ответ сохраняется внутри границ.|Каждая итерация сокращает размер примерно вдвое.|У одинаковых значений найдётся самое левое.","Поиск O(log n), чтение входа O(n), хранение O(n).","Без +1 в l = m+1 цикл может застрять.",
("Можно ли так искать в несортированном списке?",["Да","Нет, нужна монотонность","Только чётные числа"],1,"Отбрасывать половину можно лишь зная порядок."),[arr([2,5,5,9],5),arr([1],2),arr([3],0),arr([2,2,2],2),arr(list(range(0,20000,2)),12345)],lambda s:next((i+1 for i,v in enumerate(ints(s)[2:]) if v>=ints(s)[1]),-1))

def ropes_ref(s):
    v=ints(s); k=v[1];a=v[2:]
    return max([0]+[x for x in range(1,max(a)+1) if sum(y//x for y in a)>=k])
add("answer","Искать не элемент, а ответ","Поиск по ответу",7,"Основной",
"Иногда проверить ответ легче, чем сразу найти лучший. Из верёвки длины a получается a // length кусков длины length.|Если длина подходит, любая меньшая тоже подходит. Это монотонность. Ищем максимальную подходящую длину; l = 0 — условно подходящая граница, r = max(a)+1 — точно неподходящая. Ноль не проверяем делением.",
"a = [8, 5]\nlength = 3\nprint(sum(x // length for x in a))  # 3 куска",
"Из n верёвок нужно вырезать не менее k одинаковых кусков целой положительной длины. Найди максимальную длину; если нельзя получить даже длину 1, выведи 0.","n k, затем n длин; 1 ≤ n ≤ 100000, 1 ≤ k ≤ 10⁹, 1 ≤ длина ≤ 10⁹.","Максимальная целая длина.","n, k = map(int, input().split())\na = list(map(int, input().split()))\nl, r = 0, max(a) + 1\n# Проверь длину m бинарным поиском\n",
"n, k = map(int, input().split())\na = list(map(int, input().split()))\nl, r = 0, max(a) + 1\nwhile r - l > 1:\n    m = (l + r) // 2\n    if sum(x // m for x in a) >= k:\n        l = m\n    else:\n        r = m\nprint(l)",
["Для заданной длины m количество кусков — sum(x // m for x in a).","Если кусков хватает, попробуй длину больше.","Цикл while r - l > 1 не проверяет m = 0."],
"Проверка считает куски независимо по каждой верёвке.|Увеличение длины никогда не увеличивает число кусков.|Инвариант: l подходит, r не подходит, ответ между ними.","O(n log M) времени, O(n) памяти, M — максимальная длина.","Остатки разных верёвок нельзя склеить, поэтому sum(a) // m неверно.",
("Если длина 6 подходит, обязательно ли подходит 5?",["Да","Нет","Только при чётном k"],0,"Укорочение кусков не уменьшает их количество."),[arr([8,5],3),arr([1],2),arr([10],1),arr([2,2],4)]+[arr([R.randrange(1,100) for _ in range(8)],R.randrange(1,80)) for _ in range(5)],ropes_ref)

add("pointers","Два указателя вместо всех пар","Два указателя",8,"Основной",
"Отсортируем числа. Поставим l в начало, r в конец. Если сумма меньше нужной, левое число слишком мало — двигаем l. Если больше — уменьшаем r.|Почему можно отбросить число: с текущим самым большим партнёром маленькая сумма не дотягивает; с остальными будет ещё меньше. Каждый указатель проходит список лишь раз.",
"a = [1, 4, 6, 9]\n# Ищем 10: a[0] + a[3] = 10\n# Индексы должны быть разными: l < r",
"Есть ли в списке два элемента с разными индексами, сумма которых равна s? Список изначально не отсортирован.","n s, затем n чисел; 1 ≤ n ≤ 200000; |a[i]|, |s| ≤ 10⁹.","YES или NO.","n, s = map(int, input().split())\na = sorted(map(int, input().split()))\nl, r = 0, n - 1\n# Сравни сумму крайних кандидатов\n",
"n, s = map(int, input().split())\na = sorted(map(int, input().split()))\nl, r = 0, n - 1\nfound = False\nwhile l < r:\n    total = a[l] + a[r]\n    if total == s:\n        found = True\n        break\n    if total < s:\n        l += 1\n    else:\n        r -= 1\nprint('YES' if found else 'NO')",["Сначала сортировка.","Сумма мала — увеличь l; велика — уменьши r.","Условие l < r запрещает использовать один элемент дважды."],
"Сортировка делает изменение суммы предсказуемым.|После каждого неуспеха отбрасывается один невозможный кандидат.|break завершает цикл после найденной пары.","O(n log n) с сортировкой; сам поиск O(n).","Для единственного числа 5 и суммы 10 ответ NO.",
("Сумма слишком большая. Куда двигать указатель?",["l вправо","r влево","Оба наружу"],1,"Правое число станет меньше."),[arr([9,1,6,4],10),arr([5],10),arr([5,5],10),arr([-4,7,2],3),arr([1,2,3],20)]+[arr([R.randrange(-20,20) for _ in range(20)],R.randrange(-20,20)) for _ in range(4)],lambda s:"YES" if any(a+b==ints(s)[1] for a,b in itertools.combinations(ints(s)[2:],2)) else "NO")

def window_ref(s):
    v=ints(s);a=v[2:];return max([0]+[j-i for i in range(len(a)) for j in range(i+1,len(a)+1) if sum(a[i:j])<=v[1]])
add("window","Скользящее окно","Два указателя",8,"Основной",
"Окно — непрерывный кусок списка между l и r. Прибавляй новое число справа; пока сумма превышает k, убирай числа слева.|Это работает здесь, потому что числа неотрицательные: расширение не уменьшает сумму, сжатие не увеличивает. Каждый элемент добавляется и удаляется не более одного раза.",
"# a = [2, 1, 4], k = 4\n# [2] → сумма 2\n# [2, 1] → сумма 3, длина 2\n# [2, 1, 4] → 7: убираем 2, затем 1 → [4]",
"Найди максимальную длину непрерывного отрезка с суммой не больше k. Допускается пустой отрезок длины 0.","n k; затем n неотрицательных чисел; 1 ≤ n ≤ 200000; 0 ≤ a[i] ≤ 10⁹, 0 ≤ k ≤ 10¹⁸.","Максимальная длина.","n, k = map(int, input().split())\na = list(map(int, input().split()))\nl = total = best = 0\n# Двигай правую границу и сжимай окно\n",
"n, k = map(int, input().split())\na = list(map(int, input().split()))\nl = total = best = 0\nfor r in range(n):\n    total += a[r]\n    while total > k:\n        total -= a[l]\n        l += 1\n    best = max(best, r - l + 1)\nprint(best)",
["Добавь a[r] к сумме.","Пока сумма велика, вычитай a[l] и увеличивай l.","После сжатия длина окна — r - l + 1."],
"После внутреннего while сумма допустима.|Для текущего r это самое длинное допустимое окно, которое ещё можно получить движением l вправо.|Сохраняй максимум среди всех правых границ.","O(n) времени, O(n) памяти для входа.","При отрицательных числах этот алгоритм в общем случае неверен.",
("Почему два вложенных цикла здесь дают O(n)?",["while не считается","Каждый указатель движется только вперёд","Всегда три итерации"],1,"Суммарно l сдвигается не более n раз."),[arr([2,1,4],4),arr([5],0),arr([0,0,0],0),arr([2,2],4)]+[arr([R.randrange(10) for _ in range(30)],R.randrange(30)) for _ in range(5)],window_ref)

def bracket_ref(s):
    while '()' in s:s=s.replace('()','')
    return 'YES' if not s else 'NO'
add("stack","Стек: последний пришёл — первый ушёл","Стек",9,"Основной",
"Стек удобно представить стопкой тарелок: добавляем и снимаем сверху. В Python это список с append() и pop().|При '(' кладём открывающую скобку, при ')' снимаем одну. Если снимать нечего — ошибка. В конце стек должен быть пуст. Для одного вида скобок достаточно счётчика баланса.",
"stack = []\nstack.append('(')\nprint(stack.pop())  # (\nprint(len(stack))  # 0",
"Проверь корректность строки из круглых скобок. Каждая закрывающая должна иметь ещё не закрытую открывающую слева.","Непустая строка из '(' и ')', длина ≤ 200000.","YES или NO.","s = input().strip()\nstack = []\nok = True\n# Обработай скобки\n",
"s = input().strip()\nstack = []\nok = True\nfor c in s:\n    if c == '(':\n        stack.append(c)\n    elif stack:\n        stack.pop()\n    else:\n        ok = False\n        break\nprint('YES' if ok and not stack else 'NO')",["Открывающую добавляй в стек.","Перед pop() убедись, что стек не пуст.","После обхода не должно остаться незакрытых скобок."],
"Стек хранит только ещё не закрытые скобки.|Закрывающая сопоставляется последней открывающей.|Ни нехватки открывающих, ни остатка в конце быть не должно.","O(n) времени, O(n) памяти; баланс позволяет O(1) памяти.","Равное число '(' и ')' недостаточно: строка ')(' неверна.",
("Корректна ли строка ')('?",["Да, скобок поровну","Нет","Зависит от пробелов"],1,"Первую закрывающую нечем сопоставить."),["(())()","(",")","()","())(","()"*1000,"((()))"],bracket_ref)

def event_case(a):return str(len(a))+'\n'+''.join(f'{x} {y}\n' for x,y in a)
def events_ref(s):
    v=ints(s);e=list(zip(v[1::2],v[2::2]));best=0
    for mask in range(1<<len(e)):
        a=sorted(e[i] for i in range(len(e)) if mask>>i&1)
        if all(a[i][1]<=a[i+1][0] for i in range(len(a)-1)):best=max(best,len(a))
    return best
add("greedy","Жадный выбор с объяснением","Жадные алгоритмы",9,"Основной",
"Жадный алгоритм выбирает лучший шаг сейчас. Он работает не всегда — выбор нужно обосновать.|Для максимального числа встреч выбирай встречу с самым ранним концом. Её можно поставить вместо первой встречи любого оптимального расписания: она освободит время не позже. Затем повторяй для оставшихся.",
"events = [(1, 10), (2, 3), (3, 4)]\nprint(sorted(events, key=lambda e: e[1]))\n# [(2, 3), (3, 4), (1, 10)]",
"В одной комнате проходят встречи [start, end). Выбери максимальное количество непересекающихся встреч. Новая может начаться ровно в момент окончания предыдущей.","n, затем n строк start end; 1 ≤ n ≤ 200000; 0 ≤ start < end ≤ 10⁹.","Максимальное количество встреч.","n = int(input())\nevents = [tuple(map(int, input().split())) for _ in range(n)]\n# Отсортируй по окончанию\n",
"n = int(input())\nevents = [tuple(map(int, input().split())) for _ in range(n)]\nevents.sort(key=lambda e: e[1])\nlast = -1\nanswer = 0\nfor start, end in events:\n    if start >= last:\n        answer += 1\n        last = end\nprint(answer)",
["Раннее начало и короткая длительность не гарантируют оптимальности.","Сортируй по end.","При start >= last выбирай встречу и обновляй last = end."],
"Самое раннее окончание оставляет максимум возможностей.|Проверяй совместимость с последней выбранной встречей.|Обменный аргумент объясняет, почему локальный выбор сохраняет оптимум.","O(n log n) времени, O(n) памяти.","Для встреч с разной ценностью этот жадный алгоритм уже не решает задачу максимальной ценности.",
("По какому признаку сортируем?",["Начало","Длительность","Окончание"],2,"Ранний конец освобождает комнату раньше."),[event_case([(1,10),(2,3),(3,4)]),event_case([(0,1)]),event_case([(1,4),(1,4),(1,4)]),event_case([(0,2),(2,3),(3,5)])]+[event_case([(x:=R.randrange(10),x+R.randrange(1,6)) for _ in range(9)]) for _ in range(4)],events_ref)

add("gcd","НОД, НОК и целые числа","Теория чисел",10,"Основной",
"НОД(a,b) — самый большой общий делитель. Алгоритм Евклида повторяет a,b = b,a%b, пока b не ноль. Остатки уменьшаются.|НОК — наименьшее общее кратное. Для положительных чисел НОК(a,b) = a // НОД(a,b) * b. Есть готовый math.gcd. Остаток % m полезен для циклов и огромных ответов.",
"from math import gcd\nprint(gcd(12, 18))  # 6\nprint(12 // gcd(12, 18) * 18)  # 36",
"Два сигнала повторяются каждые a и b секунд. В момент 0 они прозвучали вместе. Через сколько секунд впервые совпадут снова?",
"Два положительных числа a b; 1 ≤ a,b ≤ 10¹².","Первое положительное время совпадения.","from math import gcd\na, b = map(int, input().split())\n# Найди НОК\n",
"from math import gcd\na, b = map(int, input().split())\nprint(a // gcd(a, b) * b)",["Нужное время делится и на a, и на b.","Это наименьшее общее кратное.","Раздели a на gcd(a, b), затем умножь на b."],
"Любое общее время — общее кратное периодов.|Деление произведения на НОД убирает общий множитель, учтённый дважды.|Все операции остаются целочисленными.","O(log min(a,b)) шагов Евклида; большие целые имеют свою стоимость.","Используй //, а не /, чтобы не получить неточный float.",
("Когда совпадут сигналы с периодами 4 и 6?",["2","10","12"],2,"12 — первое положительное число, делящееся и на 4, и на 6."),["4 6","1 1","7 7","13 17","1000000000000 999999999999","12 18"],lambda s:math.lcm(*ints(s)))

add("sieve","Простые числа: решето","Теория чисел",10,"Основной",
"Простое число больше 1 и имеет ровно два положительных делителя: 1 и себя. 0 и 1 не простые.|Решето: пометь числа возможными простыми. Для каждого ещё не вычеркнутого p вычеркни p*p, p*p+p, … Меньшие кратные уже обработаны. Достаточно p*p ≤ n.",
"# До 10 простые: 2, 3, 5, 7\n# Для 2 вычёркиваем 4, 6, 8, 10\n# Для 3 — 9",
"Посчитай простые числа от 2 до n включительно.","Одно целое n; 0 ≤ n ≤ 1000000.","Количество простых чисел.","n = int(input())\nprime = [True] * (n + 1)\n# Отдельно обработай 0 и 1\n",
"n = int(input())\nprime = [True] * (n + 1)\nprime[0] = False\nif n >= 1:\n    prime[1] = False\np = 2\nwhile p * p <= n:\n    if prime[p]:\n        for x in range(p * p, n + 1, p):\n            prime[x] = False\n    p += 1\nprint(sum(prime))",
["Значения False для 0 и 1 обязательны.","У range есть шаг: range(p*p, n+1, p).","True при суммировании считается единицей."],
"Каждое составное число имеет делитель не больше своего корня.|Значит, после обработки этих делителей все составные вычеркнуты.|Оставшиеся True соответствуют простым.","O(n log log n) времени, O(n) памяти.","При n = 0 обращение prime[1] выйдет за границы.",
("Является ли 1 простым?",["Да","Нет","Только в Python"],1,"У 1 только один положительный делитель."),["10","0","1","2","49","1000","997"],lambda s:sum(all(x%d for d in range(2,math.isqrt(x)+1)) for x in range(2,int(s)+1)))

def subset_ref(s):
    v=ints(s);a=v[2:];return sum(sum(a[i] for i in range(len(a)) if mask>>i&1)==v[1] for mask in range(1<<len(a)))
add("recursion","Рекурсия: взять или пропустить","Рекурсия",11,"Основной",
"Рекурсия — функция вызывает себя с меньшей задачей. Всегда нужен базовый случай, который завершает вызовы.|Для каждого элемента два решения: взять или не взять. dfs(i, total) считает способы, когда первые i элементов уже рассмотрены. При i == n сравни сумму с целью. Разные индексы считаются разными выборами.",
"def countdown(n):\n    if n == 0:\n        return\n    print(n)\n    countdown(n - 1)\n\ncountdown(3)",
"Сколько подмножеств индексов имеют сумму элементов ровно s? Пустое подмножество тоже учитывается.","n s; затем n неотрицательных чисел. 1 ≤ n ≤ 18; 0 ≤ s, a[i] ≤ 100000.","Количество подмножеств.","n, s = map(int, input().split())\na = list(map(int, input().split()))\ndef dfs(i, total):\n    # Базовый случай и две ветки\n    pass\nprint(dfs(0, 0))",
"n, s = map(int, input().split())\na = list(map(int, input().split()))\ndef dfs(i, total):\n    if i == n:\n        return int(total == s)\n    return dfs(i + 1, total) + dfs(i + 1, total + a[i])\nprint(dfs(0, 0))",["В конце верни 1, если сумма нужная, иначе 0.","Одна ветка оставляет total, другая прибавляет a[i].","Сложи число способов из обеих веток."],
"Каждый путь по дереву решений соответствует одному подмножеству.|Индекс увеличивается, поэтому рекурсия заканчивается.|При нулевых элементах разные пути могут иметь одинаковую сумму — учитывать нужно все.","O(2ⁿ) времени, O(n) глубины стека. Только для малого n.","Нельзя останавливать поиск сразу при total == s: оставшиеся нули создают дополнительные варианты.",
("Сколько подмножеств у 3 индексов?",["3","6","8"],2,"По два выбора на каждый: 2³ = 8."),[arr([1,2,3],3),arr([0],0),arr([0,0,0],0),arr([5],3),arr([1,1,1],2)]+[arr([R.randrange(5) for _ in range(8)],R.randrange(12)) for _ in range(4)],subset_ref)

def stairs(n):
    a,b=1,1
    for _ in range(int(n)):a,b=b,(a+b)%1000000007
    return a
add("dp","Динамика: не считать одно дважды","Динамическое программирование",11,"Основной",
"DP (динамическое программирование) сохраняет ответы на маленькие задачи. Сначала назови состояние словами, затем базу, переход и порядок вычисления.|Для лестницы dp[i] — число способов дойти до ступеньки i шагами 1 или 2. Последний шаг пришёл с i-1 или i-2: dp[i] = dp[i-1] + dp[i-2]. dp[0] = 1 — один способ остаться внизу.",
"# dp[0] = 1\n# dp[1] = 1\n# dp[2] = 2: 1+1, 2\n# dp[3] = 3: 1+1+1, 1+2, 2+1",
"Сколько способов подняться на n ступенек, делая шаг на 1 или 2 ступеньки? Ответ выведи по модулю 1000000007.","0 ≤ n ≤ 100000.","Число способов по указанному модулю.","n = int(input())\nMOD = 1000000007\ndp = [0] * (n + 1)\ndp[0] = 1\n# Заполни dp\n",
"n = int(input())\nMOD = 1000000007\ndp = [0] * (n + 1)\ndp[0] = 1\nfor i in range(1, n + 1):\n    dp[i] = dp[i - 1]\n    if i >= 2:\n        dp[i] += dp[i - 2]\n    dp[i] %= MOD\nprint(dp[n])",["Разбей способы по размеру последнего шага.","Для i = 1 не обращайся к dp[-1].","Бери остаток на каждой ступеньке."],
"Две группы способов не пересекаются и покрывают все варианты.|Малые состояния уже известны, когда вычисляется следующее.|Модуль ограничивает размер чисел.","O(n) времени и памяти; память можно уменьшить до O(1).","Без базового dp[0] = 1 все значения останутся нулями.",
("Что означает dp[i]?",["Номер ступеньки","Число способов дойти до i","Длина последнего шага"],1,"Смысл состояния определяет переход."),["3","0","1","2","10","100000"],stairs)

def coins_ref(s):
    v=ints(s);target=v[1];coins=v[2:];q=collections.deque([(0,0)]);seen={0}
    while q:
        x,d=q.popleft()
        if x==target:return d
        for c in coins:
            if x+c<=target and x+c not in seen:seen.add(x+c);q.append((x+c,d+1))
    return -1
add("coins","DP на минимум: монеты","Динамическое программирование",12,"Основной",
"Жадно брать крупнейшую монету нельзя для произвольных номиналов: для 1, 3, 4 сумма 6 лучше как 3+3, а не 4+1+1.|dp[x] — минимум монет для суммы x. Начни dp[0]=0, остальные — недостижимы. Для каждой монеты c ≤ x попробуй dp[x-c]+1. Монет каждого номинала неограниченно.",
"# Номиналы 1, 3, 4\n# dp[0]=0, dp[1]=1, dp[2]=2\n# dp[3]=1, dp[4]=1, dp[5]=2, dp[6]=2",
"Набери сумму s минимальным числом монет. Каждый номинал можно использовать сколько угодно раз. Если сумма недостижима, выведи -1.","n s; затем n положительных номиналов; 1 ≤ n ≤ 50, 0 ≤ s ≤ 10000, 1 ≤ c ≤ 10000.","Минимум монет или -1.","n, s = map(int, input().split())\ncoins = list(map(int, input().split()))\nINF = s + 1\ndp = [INF] * (s + 1)\ndp[0] = 0\n# Перебери суммы и последнюю монету\n",
"n, s = map(int, input().split())\ncoins = list(map(int, input().split()))\nINF = s + 1\ndp = [INF] * (s + 1)\ndp[0] = 0\nfor x in range(1, s + 1):\n    for c in coins:\n        if c <= x:\n            dp[x] = min(dp[x], dp[x - c] + 1)\nprint(dp[s] if dp[s] < INF else -1)",
["Недостижимое состояние должно быть больше любого реального ответа.","Попробуй каждый номинал как последнюю монету.","Если dp[s] осталось INF, ответа нет."],
"Положительные номиналы гарантируют, что x-c меньше x.|Выбирай минимум по всем возможным последним монетам.|INF = s+1 безопасно: реальный ответ не превосходит s.","O(n·s) времени, O(s) памяти.","Жадное решение даёт неверный ответ на монетах 1,3,4 и сумме 6.",
("Минимум монет для 6 при номиналах 1,3,4?",["3","2","1"],1,"Две монеты по 3."),[arr([1,3,4],6),arr([2],3),arr([7],0),arr([5],10),arr([2,5,7],27),arr([4,6],18)],coins_ref)

def knap_case(items,w):return f'{len(items)} {w}\n'+''.join(f'{a} {b}\n' for a,b in items)
def knap_ref(s):
    v=ints(s);items=list(zip(v[2::2],v[3::2]));return max(sum(items[i][1] for i in range(len(items)) if mask>>i&1) for mask in range(1<<len(items)) if sum(items[i][0] for i in range(len(items)) if mask>>i&1)<=v[1])
add("knapsack","Рюкзак: предмет только один раз","Динамическое программирование",12,"Углубление",
"dp[c] — максимальная ценность при вместимости c. Для предмета веса w и ценности v попробуй dp[c-w]+v.|В рюкзаке 0/1 каждый предмет можно взять один раз. Поэтому вместимости перебирают СВЕРХУ ВНИЗ. Тогда dp[c-w] ещё относится к предыдущему набору предметов.",
"# Один предмет: вес 2, ценность 3. Вместимость 4.\n# Снизу вверх дали бы 6: один предмет использован дважды.\n# Сверху вниз правильный ответ 3.",
"Выбери набор предметов с максимальной общей ценностью и общим весом не больше W. Каждый предмет доступен один раз.","n W, затем n строк вес ценность; 1 ≤ n ≤ 100, 0 ≤ W ≤ 10000; 1 ≤ вес ≤ 10000, 0 ≤ ценность ≤ 10⁶.","Максимальная ценность.","n, W = map(int, input().split())\ndp = [0] * (W + 1)\nfor _ in range(n):\n    w, v = map(int, input().split())\n    # Обнови dp сверху вниз\n",
"n, W = map(int, input().split())\ndp = [0] * (W + 1)\nfor _ in range(n):\n    w, v = map(int, input().split())\n    for c in range(W, w - 1, -1):\n        dp[c] = max(dp[c], dp[c - w] + v)\nprint(dp[W])",["У каждого предмета два варианта: пропустить или взять.","Используй range(W, w - 1, -1).","Сравни старое dp[c] и dp[c-w] + v."],
"Старое значение соответствует пропуску.|Новое берёт текущий предмет и лучший набор из предыдущих.|Обратный порядок не даёт повторно использовать текущий предмет.","O(nW) времени, O(W) памяти. W — число, поэтому это псевдополиномиальная сложность.","Сортировка по ценности/весу не решает рюкзак 0/1 в общем случае.",
("Почему вместимость перебирают вниз?",["Чтобы использовать предмет один раз","Так красивее","Иначе список отсортируется"],0,"Нижние состояния ещё не обновлены текущим предметом."),[knap_case([(2,3),(3,4),(4,5)],5),knap_case([(2,3)],4),knap_case([(1,5)],0),knap_case([(8,9)],7)]+[knap_case([(R.randrange(1,8),R.randrange(1,20)) for _ in range(9)],15) for _ in range(4)],knap_ref)

def grid_ref(s):
    lines=s.splitlines();n,m=map(int,lines[0].split());g=lines[1:];dist={ (0,0):0};q=collections.deque([(0,0)])
    if g[0][0]=='#' or g[-1][-1]=='#':return -1
    while q:
        x,y=q.popleft()
        if (x,y)==(n-1,m-1):return dist[x,y]
        for dx,dy in [(1,0),(-1,0),(0,1),(0,-1)]:
            a,b=x+dx,y+dy
            if 0<=a<n and 0<=b<m and g[a][b]!='#' and (a,b) not in dist:dist[a,b]=dist[x,y]+1;q.append((a,b))
    return -1
add("bfs","BFS: кратчайший путь по клеткам","Графы",13,"Основной",
"Граф — вершины и связи между ними. В сетке вершина — свободная клетка, связь — шаг к соседней. BFS (обход в ширину) идёт слоями расстояния: 0, 1, 2…|Очередь deque берёт старые элементы через popleft(), новые добавляет через append(). Отмечай клетку посещённой сразу при добавлении, чтобы не ставить её в очередь снова.",
"from collections import deque\nq = deque([(0, 0)])\nx, y = q.popleft()\n# Соседи: (x+1,y), (x-1,y), (x,y+1), (x,y-1)",
"Найди кратчайший путь из левого верхнего угла в правый нижний по свободным клеткам. '.' — свободно, '#' — стена. Разрешены четыре направления. Если пути нет, выведи -1.","n m, затем n строк длины m; 1 ≤ n,m ≤ 200. Старт или финиш тоже могут быть стеной.","Количество шагов или -1.","from collections import deque\nn, m = map(int, input().split())\ngrid = [input().strip() for _ in range(n)]\n# Создай очередь и таблицу расстояний\n",
"from collections import deque\nn, m = map(int, input().split())\ng = [input().strip() for _ in range(n)]\nd = [[-1] * m for _ in range(n)]\nq = deque()\nif g[0][0] == '.':\n    d[0][0] = 0\n    q.append((0, 0))\nwhile q:\n    x, y = q.popleft()\n    for dx, dy in [(1,0),(-1,0),(0,1),(0,-1)]:\n        nx, ny = x + dx, y + dy\n        if 0 <= nx < n and 0 <= ny < m and g[nx][ny] == '.' and d[nx][ny] == -1:\n            d[nx][ny] = d[x][y] + 1\n            q.append((nx, ny))\nprint(d[n - 1][m - 1])",["В d храни -1 для непосещённых клеток.","Сосед получает расстояние текущей клетки плюс 1.","Проверяй границы ДО обращения к сетке."],
"BFS извлекает вершины в порядке неубывания расстояния.|Первое посещение клетки даёт кратчайший путь, поскольку все шаги стоят 1.|Финиш со значением -1 недостижим.","O(nm) времени и памяти.","[[−1]*m]*n создаёт общие строки. Используй генерацию отдельных списков.",
("Когда отмечать клетку посещённой?",["При добавлении в очередь","После окончания всего BFS","Никогда"],0,"Иначе одна клетка многократно добавится через разных соседей."),["3 4\n....\n.##.\n....","1 1\n.","1 1\n#","2 2\n.#\n#.","2 3\n...\n..#","4 5\n.....\n####.\n.....\n.####"],grid_ref)

def graph_case(n,edges):return f'{n} {len(edges)}\n'+''.join(' '.join(map(str,e))+'\n' for e in edges)
def comp_ref(s):
    v=ints(s);n=v[0];groups=[{i} for i in range(1,n+1)]
    for a,b in zip(v[2::2],v[3::2]):
        ga=next(g for g in groups if a in g);gb=next(g for g in groups if b in g)
        if ga is not gb:ga.update(gb);groups.remove(gb)
    return len(groups)
add("dfs","DFS: найти компоненты связности","Графы",13,"Основной",
"Компонента — группа вершин, между которыми можно пройти по рёбрам. Список смежности g[v] хранит соседей v.|DFS (обход в глубину) идёт по одному пути, затем возвращается. Реализуй его стеком: это избегает ограничения глубины рекурсии Python. Каждый старт из ещё не посещённой вершины открывает новую компоненту.",
"g = [[], [2], [1], []]\n# Вершины 1 и 2 связаны; 3 изолирована.\n# Всего две компоненты.",
"Дан неориентированный граф. Посчитай компоненты связности, включая изолированные вершины.","n m, затем m пар u v. Вершины 1…n; 1 ≤ n ≤ 200000; 0 ≤ m ≤ 200000. Петли и повторные рёбра допустимы.","Количество компонент.","n, m = map(int, input().split())\ng = [[] for _ in range(n)]\n# Прочитай рёбра и запусти обходы\n",
"n, m = map(int, input().split())\ng = [[] for _ in range(n)]\nfor _ in range(m):\n    u, v = map(int, input().split())\n    u -= 1\n    v -= 1\n    g[u].append(v)\n    g[v].append(u)\nseen = [False] * n\nanswer = 0\nfor start in range(n):\n    if seen[start]:\n        continue\n    answer += 1\n    seen[start] = True\n    stack = [start]\n    while stack:\n        u = stack.pop()\n        for v in g[u]:\n            if not seen[v]:\n                seen[v] = True\n                stack.append(v)\nprint(answer)",
["Для неориентированного ребра добавь обе стороны.","Внешний цикл должен проверить все вершины, даже без рёбер.","Увеличивай число компонент перед новым обходом."],
"Один обход помечает всю компоненту.|Другой обход не попадёт в уже посещённые вершины.|Количество запусков равно количеству компонент.","O(n+m) времени и памяти.","В графе с 5 вершинами без рёбер ответ 5, а не 0.",
("Сколько компонент у трёх вершин без рёбер?",["0","1","3"],2,"Каждая изолированная вершина образует компоненту."),[graph_case(5,[(1,2),(2,3),(4,5)]),graph_case(1,[]),graph_case(5,[]),graph_case(3,[(1,1),(1,2),(1,2)]),graph_case(8,[(R.randrange(1,9),R.randrange(1,9)) for _ in range(10)])],comp_ref)

def weighted_ref(s):
    v=ints(s);n,m=v[:2];dist=[math.inf]*n;dist[0]=0;edges=list(zip(v[2::3],v[3::3],v[4::3]))
    for _ in range(n):
        for a,b,w in edges:
            dist[b-1]=min(dist[b-1],dist[a-1]+w);dist[a-1]=min(dist[a-1],dist[b-1]+w)
    return -1 if math.isinf(dist[-1]) else dist[-1]
add("dijkstra","Дейкстра: когда дороги разной длины","Взвешенные графы",14,"Углубление",
"BFS годится для одинаковой цены шага. При неотрицательных разных весах выбираем ещё не обработанную вершину с минимальным расстоянием.|heapq — куча, быстро отдающая минимум. В ней пары (расстояние, вершина). При улучшении кладём новую пару; старую позже пропускаем, если расстояние уже устарело.",
"import heapq\npq = [(5, 'B'), (2, 'A')]\nheapq.heapify(pq)\nprint(heapq.heappop(pq))  # (2, 'A')",
"Найди кратчайший путь из вершины 1 в n в неориентированном графе с неотрицательными весами.","n m, затем m строк u v w; 1 ≤ n ≤ 100000, 0 ≤ m ≤ 200000, 0 ≤ w ≤ 10⁹; вершины 1…n.","Длина пути или -1, если пути нет.","import heapq\nn, m = map(int, input().split())\ng = [[] for _ in range(n)]\n# Прочитай рёбра с весами\n",
"import heapq\nn, m = map(int, input().split())\ng = [[] for _ in range(n)]\nfor _ in range(m):\n    u, v, w = map(int, input().split())\n    g[u-1].append((v-1, w))\n    g[v-1].append((u-1, w))\nd = [float('inf')] * n\nd[0] = 0\npq = [(0, 0)]\nwhile pq:\n    cost, u = heapq.heappop(pq)\n    if cost != d[u]:\n        continue\n    for v, w in g[u]:\n        if cost + w < d[v]:\n            d[v] = cost + w\n            heapq.heappush(pq, (d[v], v))\nprint(-1 if d[-1] == float('inf') else d[-1])",
["В списке смежности храни пары (сосед, вес).","Стартовое расстояние 0, остальные — бесконечность.","Если найден более короткий путь, обнови d и добавь пару в кучу."],
"Куча выбирает самый близкий доступный кандидат.|Неотрицательные веса гарантируют корректность выбора.|Устаревшие записи отбрасываются, чтобы не повторять лишнюю работу.","O((n+m) log(n+m)) времени, O(n+m) памяти для этой реализации с дубликатами в куче.","При отрицательных весах Дейкстру использовать нельзя.",
("Когда нужен BFS вместо Дейкстры?",["Все рёбра весят 1","Есть отрицательные рёбра","Никогда"],0,"При равных весах обычная очередь дешевле и достаточна."),[graph_case(4,[(1,2,5),(1,3,1),(3,2,1),(2,4,2)]),graph_case(1,[]),graph_case(3,[(1,2,1)]),graph_case(3,[(1,3,9),(1,2,0),(2,3,0)]),graph_case(8,[(R.randrange(1,9),R.randrange(1,9),R.randrange(20)) for _ in range(20)])],weighted_ref)

def dsu_ref(s):
    lines=s.splitlines();n,q=map(int,lines[0].split());groups=[{i} for i in range(1,n+1)];out=[]
    for line in lines[1:]:
        op,a,b=map(int,line.split());ga=next(g for g in groups if a in g);gb=next(g for g in groups if b in g)
        if op==1:
            if ga is not gb:ga.update(gb);groups.remove(gb)
        else:out.append('YES' if ga is gb else 'NO')
    return '\n'.join(out)
add("dsu","Объединения без повторного обхода","DSU",14,"Углубление",
"DSU хранит группы элементов. У каждой группы есть корень-представитель. find(x) ищет корень, union(a,b) объединяет группы.|Если корни равны, элементы уже связаны. При сжатии пути вершины переподключаются ближе к корню. Присоединение маленькой группы к большой удерживает дерево неглубоким.",
"# Сначала {1}, {2}, {3}\n# union(1,2) → {1,2}, {3}\n# find(1) == find(2) → True",
"Обрабатывай запросы: 1 a b — соединить элементы; 2 a b — проверить, в одной ли группе они находятся. Соединения не удаляются.","n q; затем q запросов; 1 ≤ n,q ≤ 200000; 1 ≤ a,b ≤ n.","Для каждого запроса типа 2 выведи YES или NO.","n, q = map(int, input().split())\nparent = list(range(n + 1))\nsize = [1] * (n + 1)\n# Напиши find и обработку запросов\n",
"n, q = map(int, input().split())\nparent = list(range(n + 1))\nsize = [1] * (n + 1)\ndef find(x):\n    while parent[x] != x:\n        parent[x] = parent[parent[x]]\n        x = parent[x]\n    return x\nfor _ in range(q):\n    op, a, b = map(int, input().split())\n    a, b = find(a), find(b)\n    if op == 2:\n        print('YES' if a == b else 'NO')\n    elif a != b:\n        if size[a] < size[b]:\n            a, b = b, a\n        parent[b] = a\n        size[a] += size[b]",
["Сравнивать нужно корни, а не непосредственных родителей.","При объединении присоединяй меньшую группу к большей.","Если a == b после find, объединение не нужно."],
"Изначально каждый элемент — отдельная группа.|find возвращает единого представителя связанного множества.|Объединения меняют родителя одного корня и размер другой группы.","O((n+q)·α(n)) амортизированно, практически близко к линейному; память O(n).","Обычный DSU не поддерживает удаление связей.",
("Что сравнить для проверки одной группы?",["a == b","parent[a] == parent[b] без find","find(a) == find(b)"],2,"У разных вершин может быть общий корень через несколько родителей."),["4 5\n2 1 2\n1 1 2\n1 2 3\n2 1 3\n2 1 4","1 2\n2 1 1\n1 1 1","3 4\n1 1 2\n1 1 2\n2 1 2\n2 2 3","5 3\n2 1 5\n1 1 5\n2 5 1"],dsu_ref)

def fenwick_ref(s):
    lines=s.splitlines();a=list(map(int,lines[1].split()));out=[]
    for line in lines[2:]:
        op,i,x=map(int,line.split())
        if op==1:a[i-1]+=x
        else:out.append(str(sum(a[i-1:x])))
    return '\n'.join(out)
add("fenwick","Если массив меняется: дерево Фенвика","Дополнительные темы",14,"Углубление",
"Префиксные суммы приходится перестраивать после изменения массива. Дерево Фенвика хранит суммы блоков и поддерживает прибавление в одной позиции и сумму префикса за O(log n).|Индексы с 1. i & -i — размер младшего двоичного блока. Для обновления идём i += i & -i, для суммы — i -= i & -i. Этот урок необязателен до уверенной базы.",
"# Префикс 7 разбивается на блоки:\n# [1..4] + [5..6] + [7]\n# 7 → 6 → 4 → 0",
"Обрабатывай изменения массива и запросы сумм: 1 i delta — прибавить delta к a[i]; 2 l r — найти сумму с l по r включительно.","n q; затем n чисел; затем q запросов. 1 ≤ n,q ≤ 100000; позиции с 1; |числа|, |delta| ≤ 10⁹.","Суммы для всех запросов типа 2.","n, q = map(int, input().split())\na = list(map(int, input().split()))\nbit = [0] * (n + 1)\n# Реализуй add и prefix\n",
"n, q = map(int, input().split())\na = list(map(int, input().split()))\nbit = [0] * (n + 1)\ndef add(i, value):\n    while i <= n:\n        bit[i] += value\n        i += i & -i\ndef prefix(i):\n    total = 0\n    while i > 0:\n        total += bit[i]\n        i -= i & -i\n    return total\nfor i, x in enumerate(a, 1):\n    add(i, x)\nfor _ in range(q):\n    op, x, y = map(int, input().split())\n    if op == 1:\n        add(x, y)\n    else:\n        print(prefix(y) - prefix(x - 1))",
["Сначала научись считать сумму префикса.","Любая сумма отрезка — разность двух префиксов.","Обновление прибавляет delta, а не заменяет значение."],
"Каждая ячейка дерева хранит свой блок.|Изменение обновляет все блоки, содержащие позицию.|Запрос складывает непересекающиеся блоки префикса.","O((n+q) log n) времени, O(n) памяти.","add(0, …) зациклится: младший бит нуля равен нулю.",
("Нужен ли Фенвик, если изменений нет?",["Обязательно","Обычно достаточно префиксных сумм","Нельзя считать суммы"],1,"Префиксные суммы проще и дают O(1) на запрос."),["3 4\n1 2 3\n2 1 3\n1 2 5\n2 2 3\n2 1 1","1 3\n-2\n2 1 1\n1 1 2\n2 1 1","4 3\n0 0 0 0\n1 4 -5\n2 1 4\n2 1 3"],fenwick_ref)

def kmp_ref(s):
    p,t=s.splitlines();return sum(t[i:i+len(p)]==p for i in range(len(t)-len(p)+1))
add("kmp","Поиск образца без отката по тексту","Дополнительные темы",14,"Углубление",
"Когда ищем все вхождения, включая перекрывающиеся, простой перебор каждого среза может стоить O(nm). КМП использует префикс-функцию.|pi[i] — длина наибольшего собственного префикса строки, совпадающего с суффиксом до позиции i. При несовпадении j = pi[j-1] переходит к следующему уже известному совпадению. Урок оставь на время после основной программы.",
"# Для 'ababa' pi = [0, 0, 1, 2, 3]\n# 'aba' встречается в 'ababa' дважды: позиции 0 и 2",
"Посчитай все вхождения образца p в текст t, включая перекрывающиеся.","Первая строка p, вторая t; обе непустые, маленькие латинские буквы; длина каждой ≤ 200000.","Количество вхождений.","p = input().strip()\nt = input().strip()\ns = p + '#' + t\n# Вычисли префикс-функцию\n",
"p = input().strip()\nt = input().strip()\ns = p + '#' + t\npi = [0] * len(s)\nanswer = 0\nfor i in range(1, len(s)):\n    j = pi[i - 1]\n    while j > 0 and s[i] != s[j]:\n        j = pi[j - 1]\n    if s[i] == s[j]:\n        j += 1\n    pi[i] = j\n    if j == len(p):\n        answer += 1\nprint(answer)",
["Соедини p, разделитель и t. Разделителя не должно быть во входе.","Когда pi[i] == len(p), закончилось очередное вхождение.","При несовпадении откатывай j через pi, не i по тексту."],
"Разделитель не позволяет совпадению стать длиннее образца.|Префикс-функция переиспользует уже найденные совпадения.|Полная длина образца в pi означает одно вхождение, включая перекрытия.","O(n+m) времени и памяти.","str.count() не считает перекрывающиеся вхождения: 'aaa'.count('aa') равно 1, а здесь нужно 2.",
("Сколько вхождений 'aa' в 'aaa' с перекрытиями?",["1","2","3"],1,"Начала на позициях 0 и 1."),["aba\nababa","aa\naaa","x\nabc","abc\nabc","abcd\nab","a\naaaaa","abab\nabababab"],kmp_ref)

# Ten new practice-contest problems. Their statements never come from locked contest tasks.
def mock(id,title,topic,task,inputs,output,solution,cases,oracle,hints,explain,complexity,base):
    src=next(x for x in lessons if x['id']==base)
    add(id,title,topic,0,'Пробный тур',"Самостоятельная задача: сначала переведи условие в вход → действие → выход.|После попытки вернись к связанному уроку и сравни ход решения.",src['example'],task,inputs,output,"# Прочитай вход и реши задачу\n",solution,hints,explain,complexity,src['trap'],(src['quiz']['question'],src['quiz']['options'],src['quiz']['answer'],src['quiz']['explanation']),cases,oracle)
    lessons[-1]['related']=base

